mapper.update:
UPDATE tianquan_oauth.oauth_resource_fence f
SET version = f.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE f.tenant_id = #{tenantId} AND f.id = #{id} AND f.version = #{expectedVersion} AND f.deleted_at IS NULL
  AND EXISTS (SELECT 1 FROM tianquan_oauth.oauth_resource r
              WHERE r.tenant_id = #{tenantId} AND r.id = #{id} AND r.version = #{resourceVersion}
                AND r.resource_server_id = #{resourceServerId} AND r.deleted_at IS NULL)
